/**
 * The logo for the link-preview images, as a data URL. Generated — do not edit.
 *
 * The client's logo downscaled to 220×220 and encoded as JPEG (15968 bytes),
 * since satori draws PNG and JPEG but not WebP, and the art is opaque anyway.
 * To change it, re-encode the new logo at the same size and replace the string.
 *
 * Why a module and not a file read at request time: `output: 'standalone'`
 * copies only what the build traced, and the Docker image adds `.next/static`
 * but not `public/` or the source tree. A `readFile` of the PNG would pass
 * every local test and throw in production — inside an image route, where the
 * failure is a blank link preview rather than an error anyone sees. Compiled
 * into the route's own bundle, it cannot go missing.
 */
export const OG_LOGO_SIZE = 220;

export const OG_LOGO_DATA_URL =
  'data:image/jpeg;base64,';
